package run.ikaros.finance; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @Service public class PersistentFinanceService implements FinanceService{private final LedgerRepository ledgers;private final AccountRepository accounts;private final LedgerMemberRepository members;private final FinanceLedgerAccessService access;public PersistentFinanceService(LedgerRepository l,AccountRepository a,LedgerMemberRepository m,FinanceLedgerAccessService x){ledgers=l;accounts=a;members=m;access=x;}public Mono<LedgerView> createLedger(UUID a,CreateLedgerRequest q){Instant n=Instant.now();return ledgers.save(new LedgerEntity(null,a,q.name().trim(),q.baseCurrency().toUpperCase(),false,n,n,null)).flatMap(saved->members.save(new LedgerMemberEntity(null,saved.id(),a,a,LedgerMemberRole.EDITOR,n,null)).thenReturn(saved)).map(this::ledgerView);}public Flux<LedgerView> listLedgers(UUID a){return ledgers.findAllByOwnerIdOrderByCreatedAtDesc(a).map(this::ledgerView);}public Mono<AccountView> createAccount(UUID a,UUID id,CreateAccountRequest q){return access.requireEditor(a,id).then(Mono.defer(()->{BigDecimal opening=q.openingBalance()==null?BigDecimal.ZERO:q.openingBalance();Instant n=Instant.now();return accounts.save(new AccountEntity(null,id,a,q.name().trim(),q.type(),q.currency().toUpperCase(),opening,opening,q.institution(),q.maskedIdentifier(),q.credentialRef(),false,n,n,null));})).map(this::accountView);}public Flux<AccountView> listAccounts(UUID a,UUID id){return access.access(a,id).flatMapMany(r->accounts.findAllByLedgerIdOrderByCreatedAtAsc(id).map(this::accountView));}private LedgerView ledgerView(LedgerEntity l){return new LedgerView(l.id(),l.ownerId(),l.name(),l.baseCurrency(),l.archived(),l.createdAt());}private AccountView accountView(AccountEntity x){return new AccountView(x.id(),x.ledgerId(),x.name(),x.type(),x.currency(),x.openingBalance(),x.currentBalance(),x.institution(),x.maskedIdentifier(),x.credentialRef(),x.archived(),x.createdAt());}}
